mapper.update:
UPDATE event e JOIN (
SELECT #{it.pipelineId} AS pipeline_id, #{it.eventKind} AS event_kind, #{it.title} AS title, #{it.description} AS description, #{it.venueName} AS venue_name, #{it.thumbnailUrl} AS thumbnail_url, #{it.imageUrls} AS image_urls, #{it.links} AS links, #{it.reservationUrl} AS reservation_url, #{it.preReservation} AS pre_reservation, #{it.startDate} AS start_date, #{it.endDate} AS end_date, #{it.status} AS status, #{it.isPermanent} AS is_permanent, #{it.operatingHours} AS operating_hours, #{it.openDays} AS open_days, #{it.openWeekend} AS open_weekend, #{it.opensLate} AS opens_late, #{it.region1} AS region1, #{it.region2} AS region2, #{it.addressRoad} AS address_road, #{it.latitude} AS latitude, #{it.longitude} AS longitude, #{it.hasPhotoZone} AS has_photo_zone, #{it.isExperience} AS is_experience, #{it.ageLimit} AS age_limit, #{it.contact} AS contact, #{it.organizer} AS organizer, #{it.isFree} AS is_free, #{it.priceText} AS price_text
) s ON s.pipeline_id = e.pipeline_id SET e.event_kind = COALESCE(s.event_kind, e.event_kind), e.title = s.title, e.description = s.description, e.venue_name = s.venue_name, e.thumbnail_url = s.thumbnail_url, e.image_urls = s.image_urls, e.links = s.links, e.reservation_url = s.reservation_url, e.pre_reservation = s.pre_reservation, e.start_date = s.start_date, e.end_date = s.end_date, e.status = COALESCE(UPPER(s.status), e.status), e.is_permanent = COALESCE(s.is_permanent, FALSE), e.operating_hours = s.operating_hours, e.open_days = s.open_days, e.open_weekend = s.open_weekend, e.opens_late = s.opens_late, e.region1 = s.region1, e.region2 = s.region2, e.address_road = s.address_road, e.latitude = s.latitude, e.longitude = s.longitude, e.has_photo_zone = COALESCE(s.has_photo_zone, FALSE), e.is_experience = COALESCE(s.is_experience, FALSE), e.age_limit = s.age_limit, e.contact = s.contact, e.organizer = s.organizer, e.is_free = s.is_free, e.price_text = s.price_text

UPDATE place p JOIN (
SELECT #{it.pipelineId} AS pipeline_id, #{it.name} AS name, #{it.brand} AS brand, #{it.branch} AS branch, #{it.placeKind} AS place_kind, #{it.thumbnailUrl} AS thumbnail_url, #{it.imageUrls} AS image_urls, #{it.region1} AS region1, #{it.region2} AS region2, #{it.addressRoad} AS address_road, #{it.addressDetail} AS address_detail, #{it.postalCode} AS postal_code, #{it.latitude} AS latitude, #{it.longitude} AS longitude, #{it.openingHours} AS opening_hours, #{it.closedDays} AS closed_days, #{it.tel} AS tel, #{it.hasParking} AS has_parking, #{it.reservable} AS reservable, #{it.takeoutAvailable} AS takeout_available, #{it.hasRestroom} AS has_restroom, #{it.menuSummary} AS menu_summary, #{it.isActive} AS is_active
) s ON s.pipeline_id = p.pipeline_id SET p.name = s.name, p.brand = s.brand, p.branch = s.branch, p.place_kind = s.place_kind, p.thumbnail_url = s.thumbnail_url, p.image_urls = s.image_urls, p.region1 = s.region1, p.region2 = s.region2, p.address_road = s.address_road, p.address_detail = s.address_detail, p.postal_code = s.postal_code, p.latitude = s.latitude, p.longitude = s.longitude, p.opening_hours = s.opening_hours, p.closed_days = s.closed_days, p.tel = s.tel, p.has_parking = s.has_parking, p.reservable = s.reservable, p.takeout_available = s.takeout_available, p.has_restroom = s.has_restroom, p.menu_summary = s.menu_summary, p.is_active = COALESCE(s.is_active, TRUE)

mapper.insert:
INSERT INTO event_translations (event_id, language_code, title, description, operating_hours, address_display, venue_detail, age_limit, organizer, price_text) SELECT e.event_id, s.language_code, s.title, s.description, s.operating_hours, s.address_display, s.venue_detail, s.age_limit, s.organizer, s.price_text FROM (
SELECT #{it.pipelineId} AS pipeline_id, #{it.languageCode} AS language_code, #{it.title} AS title, #{it.description} AS description, #{it.operatingHours} AS operating_hours, #{it.addressDisplay} AS address_display, #{it.venueDetail} AS venue_detail, #{it.ageLimit} AS age_limit, #{it.organizer} AS organizer, #{it.priceText} AS price_text
) s JOIN event e ON e.pipeline_id = s.pipeline_id ON DUPLICATE KEY UPDATE title = VALUES(title), description = VALUES(description), operating_hours = VALUES(operating_hours), address_display = VALUES(address_display), venue_detail = VALUES(venue_detail), age_limit = VALUES(age_limit), organizer = VALUES(organizer), price_text = VALUES(price_text), deleted_at = NULL

INSERT INTO place_translations (place_id, language_code, name, brand, branch, address_display, address_detail, opening_hours_text, closed_days_text, menu_summary) SELECT p.place_id, s.language_code, s.name, s.brand, s.branch, s.address_display, s.address_detail, s.opening_hours_text, s.closed_days_text, s.menu_summary FROM (
SELECT #{it.pipelineId} AS pipeline_id, #{it.languageCode} AS language_code, #{it.name} AS name, #{it.brand} AS brand, #{it.branch} AS branch, #{it.addressDisplay} AS address_display, #{it.addressDetail} AS address_detail, #{it.openingHoursText} AS opening_hours_text, #{it.closedDaysText} AS closed_days_text, #{it.menuSummary} AS menu_summary
) s JOIN place p ON p.pipeline_id = s.pipeline_id ON DUPLICATE KEY UPDATE name = VALUES(name), brand = VALUES(brand), branch = VALUES(branch), address_display = VALUES(address_display), address_detail = VALUES(address_detail), opening_hours_text = VALUES(opening_hours_text), closed_days_text = VALUES(closed_days_text), menu_summary = VALUES(menu_summary), deleted_at = NULL
